import{_ as a,a0 as o,w as d,s as p,I as s,x as t,a1 as l,A as n,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"MidnightBSD：或许是你通往 FreeBSD 的大门 | LCTT x X-CMD","titleTemplate":false,"description":"MidnightBSD：或许是你通往 FreeBSD 的大门 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"MidnightBSD：或许是你通往 FreeBSD 的大门 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"MidnightBSD：或许是你通往 FreeBSD 的大门 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20180511 MidnightBSD Could Be Your Gateway to FreeBSD","title":"MidnightBSD：或许是你通往 FreeBSD 的大门","tag":"202002","desc":""},"relativePath":"202002/20180511 MidnightBSD Could Be Your Gateway to FreeBSD.md","filePath":"[post].md"}'),g={name:"202002/20180511 MidnightBSD Could Be Your Gateway to FreeBSD.md"};function h(u,i,b,f,k,m){const e=o("Link");return d(),p("div",null,[i[29]||(i[29]=s("h1",{id:"midnightbsd-或许是你通往-freebsd-的大门",tabindex:"-1"},[t("MidnightBSD：或许是你通往 FreeBSD 的大门 "),s("a",{class:"header-anchor",href:"#midnightbsd-或许是你通往-freebsd-的大门","aria-label":"Permalink to “MidnightBSD：或许是你通往 FreeBSD 的大门”"},"​")],-1)),i[30]||(i[30]=s("p",null,[s("img",{src:"https://www.linux.com/wp-content/uploads/2019/08/midnight_4_0.jpg",alt:""})],-1)),s("p",null,[l(e,{href:"https://www.freebsd.org/"},{default:n(()=>[...i[0]||(i[0]=[t("FreeBSD",-1)])]),_:1}),i[4]||(i[4]=t(" 是一个开源操作系统，衍生自著名的 ",-1)),s("ruby",null,[l(e,{href:"https://en.wikipedia.org/wiki/Berkeley_Software_Distribution"},{default:n(()=>[...i[1]||(i[1]=[t("伯克利软件套件",-1)])]),_:1}),i[2]||(i[2]=s("rt",null,"Berkeley Software Distribution",-1))]),i[5]||(i[5]=t("（BSD）。FreeBSD 的第一个版本发布于 1993 年，并且仍然在继续发展。2007 年左右，Lucas Holt 想要利用 OpenStep（现在是 Cocoa）的 Objective-C 框架、widget 工具包和应用程序开发工具的 ",-1)),l(e,{href:"https://en.wikipedia.org/wiki/GNUstep"},{default:n(()=>[...i[3]||(i[3]=[t("GnuStep",-1)])]),_:1}),i[6]||(i[6]=t(" 实现，来创建一个 FreeBSD 的分支。为此，他开始开发 MidnightBSD 桌面发行版。",-1))]),i[31]||(i[31]=s("p",null,"MidnightBSD（以 Lucas 的猫 Midnight 命名）仍然在积极地（尽管缓慢）开发。从 2017 年 8 月开始，可以获得最新的稳定发布版本（0.8.6）（LCTT 译注：截止至本译文发布时，当前是 2019/10/31 发布的 1.2 版）。尽管 BSD 发行版不是你所说的用户友好型发行版，但上手安装是熟悉如何处理 文本（ncurses）安装过程以及通过命令行完成安装的好方法。",-1)),i[32]||(i[32]=s("p",null,"这样，你最终会得到一个非常可靠的 FreeBSD 分支的桌面发行版。这需要花费一点精力，但是如果你是一名正在寻找扩展你的技能的 Linux 用户……这是一个很好的起点。",-1)),i[33]||(i[33]=s("p",null,"我将带你走过安装 MidnightBSD 的流程，如何添加一个图形桌面环境，然后如何安装应用程序。",-1)),i[34]||(i[34]=s("h3",{id:"安装",tabindex:"-1"},[t("安装 "),s("a",{class:"header-anchor",href:"#安装","aria-label":"Permalink to “安装”"},"​")],-1)),s("p",null,[i[9]||(i[9]=t("正如我所提到的，这是一个文本（ncurses）安装过程，因此在这里找不到可以用鼠标点击的地方。相反，你将使用你键盘的 ",-1)),i[10]||(i[10]=s("code",null,"Tab",-1)),i[11]||(i[11]=t(" 键和箭头键。在你下载",-1)),l(e,{href:"http://www.midnightbsd.org/download/"},{default:n(()=>[...i[7]||(i[7]=[t("最新的发布版本",-1)])]),_:1}),i[12]||(i[12]=t("后，将它刻录到一个 CD/DVD 或 USB 驱动器，并启动你的机器（或者在 ",-1)),l(e,{href:"https://www.virtualbox.org/"},{default:n(()=>[...i[8]||(i[8]=[t("VirtualBox",-1)])]),_:1}),i[13]||(i[13]=t(" 中创建一个虚拟机）。安装程序将打开并给你三个选项（图 1）。使用你的键盘的箭头键选择 “Install”，并敲击回车键。",-1))]),i[35]||(i[35]=r(`<p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/midnight_1.jpg" alt="MidnightBSD installer" title="MidnightBSD installer"></p><p><em>图 1: 启动 MidnightBSD 安装程序。</em></p><p>在这里要经历相当多的屏幕。其中很多屏幕是一目了然的：</p><ol><li>设置非默认键盘映射（是/否）</li><li>设置主机名称</li><li>添加可选系统组件（文档、游戏、32 位兼容性、系统源码代码）</li><li>对硬盘分区</li><li>管理员密码</li><li>配置网络接口</li><li>选择地区（时区）</li><li>启用服务（例如 ssh）</li><li>添加用户（图 2）</li></ol><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/midnight_2.jpg" alt="Adding a user" title="Adding a user"></p><p><em>图 2: 向系统添加一个用户。</em></p><p>在你向系统添加用户后，你将被进入到一个窗口中（图 3），在这里，你可以处理任何你可能忘记配置或你想重新配置的东西。如果你不需要作出任何更改，选择 “Exit”，然后你的配置就会被应用。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/mightnight_3.jpg" alt="Applying your configurations" title="Applying your configurations"></p><p><em>图 3: 应用你的配置。</em></p><p>在接下来的窗口中，当出现提示时，选择 “No”，接下来系统将重启。在 MidnightBSD 重启后，你已经为下一阶段的安装做好了准备。</p><h3 id="后安装阶段" tabindex="-1">后安装阶段 <a class="header-anchor" href="#后安装阶段" aria-label="Permalink to “后安装阶段”">​</a></h3><p>当你最新安装的 MidnightBSD 启动时，你将发现你自己处于命令提示符当中。此刻，还没有图形界面。要安装应用程序，MidnightBSD 依赖于 <code>mport</code> 工具。比如说你想安装 Xfce 桌面环境。为此，登录到 MidnightBSD 中，并发出下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mport index</span></span>
<span class="line"><span>sudo mport install xorg</span></span></code></pre></div><p>你现在已经安装好 Xorg 窗口服务器了，它允许你安装桌面环境。使用命令来安装 Xfce ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mport install xfce</span></span></code></pre></div><p>现在 Xfce 已经安装好。不过，我们必须让它同命令 <code>startx</code> 一起启用。为此，让我们先安装 nano 编辑器。发出命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mport install nano</span></span></code></pre></div><p>随着 nano 安装好，发出命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nano ~/.xinitrc</span></span></code></pre></div><p>这个文件仅包含一行内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>exec startxfce4</span></span></code></pre></div><p>保存并关闭这个文件。如果你现在发出命令 <code>startx</code>, Xfce 桌面环境将会启动。你应该会感到有点熟悉了吧（图 4）。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/midnight_4.jpg" alt=" Xfce" title="Xfce"></p><p><em>图 4: Xfce 桌面界面已准备好服务。</em></p><p>因为你不会总是想必须发出命令 <code>startx</code>，你希望启用登录守护进程。然而，它却没有安装。要安装这个子系统，发出命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mport install mlogind</span></span></code></pre></div><p>当完成安装后，通过在 <code>/etc/rc.conf</code> 文件中添加一个项目来在启动时启用 mlogind。在 <code>rc.conf</code> 文件的底部，添加以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mlogind_enable=”YES”</span></span></code></pre></div><p>保存并关闭该文件。现在，当你启动（或重启）机器时，你应该会看到图形登录屏幕。在写这篇文章的时候，在登录后我最后得到一个空白屏幕和讨厌的 X 光标。不幸的是，目前似乎并没有这个问题的解决方法。所以，要访问你的桌面环境，你必须使用 <code>startx</code> 命令。</p><h3 id="安装应用" tabindex="-1">安装应用 <a class="header-anchor" href="#安装应用" aria-label="Permalink to “安装应用”">​</a></h3><p>默认情况下，你找不到很多能可用的应用程序。如果你尝试使用 <code>mport</code> 安装应用程序，你很快就会感到沮丧，因为只能找到很少的应用程序。为解决这个问题，我们需要使用 <code>svnlite</code> 命令来查看检出的可用 mport 软件列表。回到终端窗口，并发出命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>svnlite co http://svn.midnightbsd.org/svn/mports/trunk mports</span></span></code></pre></div><p>在你完成这些后，你应该看到一个命名为 <code>~/mports</code> 的新目录。使用命令 <code>cd ~/.mports</code> 更改到这个目录。发出 <code>ls</code> 命令，然后你应该看到许多的类别（图 5）。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/midnight_5.jpg" alt="applications" title="applications"></p><p><em>图 5: mport 现在可用的应用程序类别。</em></p><p>你想安装 Firefox 吗？如果你查看 <code>www</code> 目录，你将看到一个 <code>linux-firefox</code> 列表。发出命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mport install linux-firefox</span></span></code></pre></div><p>现在你应该会在 Xfce 桌面菜单中看到一个 Firefox 项。翻找所有的类别，并使用 <code>mport</code> 命令来安装你需要的所有软件。</p><h3 id="一个悲哀的警告" tabindex="-1">一个悲哀的警告 <a class="header-anchor" href="#一个悲哀的警告" aria-label="Permalink to “一个悲哀的警告”">​</a></h3><p>一个悲哀的小警告是，<code>mport</code> （通过 <code>svnlite</code>）仅能找到的一个办公套件的版本是 OpenOffice 3 。那是非常过时的。尽管在 <code>~/mports/editors</code> 目录中能找到 Abiword ，但是它看起来不能安装。甚至在安装 OpenOffice 3 后，它会输出一个执行格式错误。换句话说，你不能使用 MidnightBSD 在办公生产效率方面做很多的事情。但是，嘿嘿，如果你周围正好有一个旧的 Palm Pilot，你可以安装 pilot-link。换句话说，可用的软件不足以构成一个极其有用的桌面发行版……至少对普通用户不是。但是，如果你想在 MidnightBSD 上开发，你将找到很多可用的工具可以安装（查看 <code>~/mports/devel</code> 目录）。你甚至可以使用命令安装 Drupal ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mport install drupal7</span></span></code></pre></div><p>当然，在此之后，你将需要创建一个数据库（MySQL 已经安装）、安装 Apache（<code>sudo mport install apache24</code>），并配置必要的 Apache 配置。</p><p>显然地，已安装的和可以安装的是一个应用程序、系统和服务的大杂烩。但是随着足够多的工作，你最终可以得到一个能够服务于特殊目的的发行版。</p><h3 id="享受-bsd-优良" tabindex="-1">享受 *BSD 优良 <a class="header-anchor" href="#享受-bsd-优良" aria-label="Permalink to “享受 *BSD 优良”">​</a></h3><p>这就是如何使 MidnightBSD 启动，并使其运行某种有用的桌面发行版的方法。它不像很多其它的 Linux 发行版一样快速简便，但是如果你想要一个促使你思考的发行版，这可能正是你正在寻找的。尽管大多数竞争对手都准备了很多可以安装的应用软件，但 MidnightBSD 无疑是一个 Linux 爱好者或管理员应该尝试的有趣挑战。</p><hr>`,46)),s("p",null,[i[15]||(i[15]=t("via: ",-1)),l(e,{href:"https://www.linux.com/learn/intro-to-linux/2018/5/midnightbsd-could-be-your-gateway-freebsd"},{default:n(()=>[...i[14]||(i[14]=[t("https://www.linux.com/learn/intro-to-linux/2018/5/midnightbsd-could-be-your-gateway-freebsd",-1)])]),_:1})]),s("p",null,[i[20]||(i[20]=t("作者：",-1)),l(e,{href:"https://www.linux.com/users/jlwallen"},{default:n(()=>[...i[16]||(i[16]=[t("Jack Wallen",-1)])]),_:1}),i[21]||(i[21]=t(" 选题：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...i[17]||(i[17]=[t("lujun9972",-1)])]),_:1}),i[22]||(i[22]=t(" 译者：",-1)),l(e,{href:"https://github.com/robsean"},{default:n(()=>[...i[18]||(i[18]=[t("robsean",-1)])]),_:1}),i[23]||(i[23]=t(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:n(()=>[...i[19]||(i[19]=[t("wxy",-1)])]),_:1})]),s("p",null,[i[26]||(i[26]=t("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...i[24]||(i[24]=[t("LCTT",-1)])]),_:1}),i[27]||(i[27]=t(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:n(()=>[...i[25]||(i[25]=[t("Linux中国",-1)])]),_:1}),i[28]||(i[28]=t(" 荣誉推出",-1))])])}const S=a(g,[["render",h]]);export{D as __pageData,S as default};
